from __future__ import annotations


FEN_CASES = [
    ("tr-g06-fen-bilimleri-note-001", "Bir uzay sergisinde ilk dört gezegen küçük ve kayalık, dıştaki dört gezegen ise çok daha büyük modellerle gösteriliyor.", "Merkür-Mars grubunda katı yüzey; Jüpiter-Neptün grubunda kalın gaz katmanları bilgisi veriliyor.", "Gezegenler yapı ve konumlarına göre içteki karasal gezegenler ile dıştaki gaz/buz devleri olarak sınıflandırılabilir.", "Model etiketlerini yalnız büyüklüğe değil yapı ve Güneş'e uzaklık ölçütlerine göre iki gruba ayırmak gerekir.", "Katı yüzey ve iç konumun aynı grupta toplanması, sınıflandırmanın tek başına renge dayanmadığını gösterir.", ["Bütün büyük gezegenler Güneş'e en yakın karasal gezegenlerdir.", "Gezegenleri sınıflandırırken yapı ve konum bilgisi kullanılamaz.", "Dış gezegenlerin tümü Dünya gibi belirgin katı yüzeylidir."], "Bilimsel sınıflandırma birden çok ayırt edici özelliği birlikte kullanır; gezegenin görünür rengi tek ölçüt değildir."),
    ("tr-g06-fen-bilimleri-note-002", "Bir grup Güneş'i basketbol topu büyüklüğünde yapıp gezegenleri aralarında birer santimetre olacak biçimde diziyor.", "Boyut ölçeği kullanıldığı hâlde uzaklıkların aynı ölçekle gösterilmesi için sınıfın çok daha uzun olması gerektiği hesaplanıyor.", "Güneş Sistemi modelinde boyut ve uzaklık ölçekleri açıkça belirtilmeli; ikisini aynı küçük alanda gerçek oranla göstermek her zaman mümkün değildir.", "Model açıklamasında boyut ve uzaklık için kullanılan ölçekleri ayrı yazıp temsil sınırını belirtmek gerekir.", "Gerekli alan hesabı, birer santimetrelik aralıkların gerçek uzaklık oranını temsil etmediğini gösterir.", ["Bir modelde bütün gezegenleri eşit büyüklükte yapmak gerçek oranı eksiksiz gösterir.", "Modelin ölçeğini açıklamak bilimsel temsil için gereksizdir.", "Boyut doğruysa gezegenler arası uzaklık rastgele seçilse de model kusursuzdur."], "Bilimsel model gerçeğin seçilmiş yönlerini temsil eder; ölçek ve temsil edilmeyen yönler kullanıcıya açıkça bildirilir."),
    ("tr-g06-fen-bilimleri-note-003", "Gündüz gökyüzünde Ay, Güneş ile Dünya arasına geliyor ve Güneş'in bir bölümü kararıyor.", "Gözlem yalnız dar bir bölgede kısa süre izleniyor; Dünya'nın gece tarafında olay görünmüyor.", "Güneş tutulması Ay'ın Güneş ile Dünya arasına girmesi ve gölgesinin Dünya'ya düşmesiyle oluşur.", "Olayı güvenli Güneş gözlem filtresiyle izleyip gölge konisini ve hizalanmayı model üzerinde göstermek gerekir.", "Dar bölgede gündüz görülmesi, olayın Ay gölgesinin Dünya üzerindeki sınırlı alanıyla ilişkili olduğunu gösterir.", ["Güneş tutulmasında Dünya, Güneş ile Ay arasına girer.", "Güneş tutulması Dünya'nın her yerinde aynı anda görülür.", "Güneş'e çıplak gözle bakmak tutulmayı güvenli biçimde inceletir."], "Tutulma çıkarımı gök cisimlerinin sırası, gölge yönü ve gözlenebilen bölge birlikte değerlendirilerek yapılır."),
    ("tr-g06-fen-bilimleri-note-004", "Bir modelde lambanın önüne Dünya küresi, onun arkasına Ay küresi yerleştiriliyor.", "Dünya'nın gölgesi Ay modelinin üzerine düştüğünde Ay yüzeyi kararıyor.", "Ay tutulması modelinde Güneş-Dünya-Ay doğrultusu kurulmalı ve Dünya'nın gölgesi Ay'a ulaşmalıdır.", "Lamba, Dünya ve Ay modellerini doğru sırada hizalayıp gölge bölgesini etiketlemek gerekir.", "Ay'ın Dünya gölgesinde kalması, modelin Ay tutulmasını temsil ettiğini gösterir.", ["Ay tutulması modelinde Ay mutlaka Güneş ile Dünya arasındadır.", "Dünya gölgesi Ay'a ulaşmadan Ay tutulması oluşur.", "Modelde ışık kaynağının konumu tutulma türünü etkilemez."], "Tutulma modeli yalnız üç küreyi içermekle yeterli olmaz; ışık kaynağı, sıra, yörünge düzlemi ve gölge ilişkisi doğru kurulmalıdır."),
    ("tr-g06-fen-bilimleri-note-005", "Bir kutuya doğuya doğru 12 N, batıya doğru 7 N kuvvet uygulanıyor.", "Dinamometre değerleri aynı doğrultuda ve zıt yönlerde; büyük kuvvet doğuya yönelmiş.", "Zıt yönlü aynı doğrultudaki kuvvetlerin bileşkesi büyüklük farkıdır ve büyük kuvvetin yönündedir.", "12 N'den 7 N'yi çıkarıp bileşkeyi 5 N doğu yönünde göstermek gerekir.", "Büyük kuvvetin doğuda olması ve farkın 5 N çıkması, net etkinin doğuya olduğunu gösterir.", ["Zıt kuvvetler her durumda toplanır ve bileşke 19 N olur.", "Bileşkenin yönü küçük kuvvetin yönü olan batıdır.", "Aynı doğrultudaki kuvvetlerin yönü hesaplamada dikkate alınmaz."], "Bileşke kuvvette büyüklük kadar yön de korunur; aynı yönlü kuvvetler toplanır, zıt yönlüler çıkarılır."),
    ("tr-g06-fen-bilimleri-note-006", "Düz yolda sabit süratle ilerleyen oyuncak arabanın motor kuvveti ile sürtünmesi eşit ölçülüyor.", "Kuvvetler zıt yönlü 4 N ve arabanın sürati ölçüm boyunca değişmiyor.", "Dengelenmiş kuvvetlerde bileşke sıfırdır; duran cisim durabilir, hareketli cisim sabit hızla hareketini sürdürebilir.", "Kuvvetleri yönleriyle gösterip net kuvveti sıfır olarak belirlemek, hareketin değişmediğini açıklamak gerekir.", "Eşit zıt kuvvetlerle süratin değişmemesi, dengelenmiş kuvvetlerin hareketi zorunlu olarak durdurmadığını gösterir.", ["Bileşke sıfırsa hareketli cisim mutlaka anında durur.", "Eşit zıt kuvvetlerin bileşkesi kuvvetlerden birine eşittir.", "Sabit süratle hareket eden cisme hiçbir kuvvet etki edemez."], "Dengelenme hareketin yokluğu değil, hızın değişmemesiyle ilgilidir; net kuvvet sıfır olduğunda ivmelenme beklenmez."),
    ("tr-g06-fen-bilimleri-note-007", "Bir koşucu 400 metrelik pisti bir tur tamamlayıp başladığı noktaya 80 saniyede dönüyor.", "Toplam yol 400 m, başlangıç ile bitiş arasındaki yer değiştirme sıfırdır.", "Sürat alınan yolun zamana oranıyla, hız ise yer değiştirme ve yönle ilişkilidir.", "Ortalama sürati 400/80=5 m/s hesaplayıp tur sonunda ortalama hız büyüklüğünün sıfır olduğunu belirtmek gerekir.", "Yol sıfır değilken yer değiştirmenin sıfır olması, sürat ile hızın aynı sonucu vermeyebileceğini gösterir.", ["Başlangıç noktasına dönen koşucunun aldığı yol da sıfırdır.", "Sürat ve hız her hareket için yönsüz ve tamamen aynı kavramdır.", "400 metreyi hesaplarken geçen zamanın hiçbir önemi yoktur."], "Sürat skaler yol bilgisini, hız ise yönlü yer değiştirmeyi kullanır; birimler ve zaman aralığı açık tutulur."),
    ("tr-g06-fen-bilimleri-note-008", "Çilek bitkisinin sürünücü gövdesinden yeni bitki oluşurken çiçekli bitkide tohum oluşumu da gözleniyor.", "Sürünücü gövdeden oluşan yavru ana bitkiye çok benzer; tohumla oluşanlarda kalıtsal çeşitlilik görülebilir.", "Eşeysiz üreme tek canlıdan ve döllenme olmadan, eşeyli üreme üreme hücrelerinin birleşmesiyle gerçekleşir.", "İki çoğalma biçimini ebeveyn sayısı, döllenme ve kalıtsal çeşitlilik ölçütleriyle karşılaştırmak gerekir.", "Benzerlik ile çeşitlilik farkı, iki üreme biçiminin kalıtsal sonuçlarının aynı olmadığını gösterir.", ["Eşeysiz üremede mutlaka iki ebeveyn ve döllenme gerekir.", "Eşeyli üreme yavrularda hiçbir kalıtsal çeşitlilik oluşturmaz.", "Bitkiler yalnız eşeysiz, hayvanlar yalnız eşeyli ürer."], "Üreme biçimleri canlı grubuna göre kalıp yargıyla değil, döllenme, ebeveyn ve yavru çeşitliliği kanıtlarıyla ayırt edilir."),
    ("tr-g06-fen-bilimleri-note-009", "Özdeş fasulye bitkilerinden biri yeterli ışık ve su, diğeri karanlık, üçüncüsü aşırı su koşulunda yetiştiriliyor.", "Yeterli koşuldaki bitki sağlıklı, karanlıktaki soluk ve uzun, aşırı sulananın kökleri zarar görmüş görünüyor.", "Bitki büyüme ve gelişmesi ışık, su, sıcaklık, mineral ve gaz alışverişi gibi etkenlerin uygun düzeyine bağlıdır.", "Tek bir etkeni değiştirerek kontrollü düzenek kurmak ve büyümeyi aynı süre boyunca ölçmek gerekir.", "Farklı olumsuz belirtiler, daha fazla su veya daha az ışığın her zaman daha iyi büyüme sağlamadığını gösterir.", ["Bitkiler ışık olmadan her zaman daha sağlıklı gelişir.", "Su miktarı arttıkça büyüme sınırsız ve sürekli artar.", "Büyümeyi karşılaştırırken bütün koşulları aynı anda değiştirmek kontrollü deneydir."], "Canlı gelişiminde etkenlerin yalnız varlığı değil uygun miktarı önemlidir; neden çıkarımı kontrollü değişkenlerle yapılır."),
    ("tr-g06-fen-bilimleri-note-010", "Dört özdeş tohumdan biri susuz, biri çok soğuk, biri havasız kapta, biri nemli ve uygun sıcaklıkta tutuluyor.", "Yalnız nemli, oksijenli ve uygun sıcaklıktaki tohum düzenli çimleniyor.", "Çimlenme için uygun sıcaklık, su ve oksijen gerekir; ışık birçok tohum için zorunlu ortak koşul değildir.", "Her deneyde yalnız bir koşulu değiştirip çimlenme yüzdesini aynı sürede karşılaştırmak gerekir.", "Üç eksik koşulda çimlenmenin olmaması, su-oksijen-sıcaklık gereksinimini destekler.", ["Bütün tohumların çimlenmesi için mutlaka güçlü ışık gerekir.", "Oksijensiz kap çimlenmeyi her zaman hızlandırır.", "Susuz tohum uygun sıcaklıktaysa kesin çimlenir."], "Çimlenme hipotezi ölçülebilir değişken, kontrol grubu ve tekrarlı gözlemle sınanır; büyüme koşullarıyla karıştırılmaz."),
    ("tr-g06-fen-bilimleri-note-011", "Kurbağanın yumurta, iribaş ve yetişkin evreleri ile kedinin yavru ve yetişkin evreleri karşılaştırılıyor.", "Kurbağada belirgin başkalaşım, kedide anne karnında gelişim ve doğum sonrası büyüme gözleniyor.", "Hayvanlarda üreme ve gelişme türlere göre yumurta, doğum, başkalaşım veya doğrudan gelişme gibi farklı yollar izleyebilir.", "Yaşam döngülerini evre sırası, üreme biçimi ve yavru-yetişkin benzerliği ölçütleriyle karşılaştırmak gerekir.", "Kurbağa ve kedideki farklı evreler, bütün hayvanların aynı gelişim yolunu izlemediğini gösterir.", ["Bütün hayvan yavruları yetişkinin küçük ve tamamen aynı kopyasıdır.", "Başkalaşım yalnız memelilerde görülür.", "Yumurta bırakan hiçbir hayvanda büyüme ve gelişme olmaz."], "Hayvan yaşam döngüsü örnekten türe özgü çıkarılır; tek bir türün gelişim modeli bütün hayvanlara genellenmez."),
    ("tr-g06-fen-bilimleri-note-012", "Bir modelde yumurtalık, yumurta kanalı ve rahim; başka bölümde testis ve sperm kanalı etiketleniyor.", "Yumurta hücresinin yumurtalıkta, sperm hücresinin testiste oluştuğu; yapıların üreme sürecinde farklı görev taşıdığı belirtiliyor.", "İnsanda üreme yapıları üreme hücrelerinin oluşması, taşınması ve gelişim için uygun ortam sağlanması gibi ilişkili görevler yürütür.", "Model etiketlerini yapıların gerçek görevleriyle eşleştirip hiçbir organı tek başına bütün süreç gibi göstermemek gerekir.", "Farklı görevlerin bir zincir oluşturması, üremenin tek bir yapı tarafından yürütülmediğini gösterir.", ["Yumurta hücresi testiste, sperm hücresi yumurtalıkta oluşur.", "Üreme sistemindeki bütün yapıların görevi tamamen aynıdır.", "Yapılar arasındaki bağlantı üreme sürecini etkilemez."], "Üreme sistemi yaşa uygun bilimsel dil, yapı-görev ilişkisi ve mahremiyet saygısıyla öğretilir; sağlık tanısı çıkarılmaz."),
    ("tr-g06-fen-bilimleri-note-013", "El sıcak yüzeye değdiğinde el hızla çekiliyor, kişi acıyı bir an sonra bilinçli olarak fark ediyor.", "Duyu siniri uyarıyı omuriliğe taşıyor, motor sinir kasa yanıt iletiyor; bilgi beyne de ulaşıyor.", "Refleks yayında omurilik hızlı yanıtı düzenleyebilir; beyin duyunun değerlendirilmesi ve bilinçli süreçlerde görev alır.", "Modelde duyu siniri-omurilik-motor sinir-kas yolunu oklarla, beyne giden bilgi yolunu ayrıca göstermek gerekir.", "Elin bilinçli değerlendirmeden önce çekilmesi, hızlı refleks yanıtında omuriliğin rolünü destekler.", ["Bütün refleksler önce uzun süre beyinde düşünülerek başlar.", "Çevresel sinirler uyarı ve yanıt iletiminde görev almaz.", "Omurilik yalnız kemikleri birbirine bağlayan bir yapıdır."], "Sinir sistemi modeli merkezi ve çevresel bölümler arasındaki bilgi akışını gösterir; refleks bilinçli davranışın tümüyle aynısı değildir."),
    ("tr-g06-fen-bilimleri-note-014", "Koşu sırasında kalp atımı ve solunum artıyor, bir süre sonra vücut değerleri dinlenme düzeyine yaklaşıyor.", "Sinirsel iletim hızlı başlıyor; hormonların etkisi daha yavaş başlayıp daha uzun sürebiliyor.", "Sinir sistemi ve iç salgı bezleri vücudun düzenlenmesinde farklı hız ve yollarla birlikte çalışır.", "Değişimleri tek bir hormona bağlamadan sinirsel ve hormonal düzenlemeyi süre ve etki bakımından karşılaştırmak gerekir.", "Hızlı ve daha uzun süreli etkilerin bir arada görülmesi, iki düzenleyici sistemin aynı olmadığını gösterir.", ["Bütün vücut düzenlemesini yalnız tek bir bez gerçekleştirir.", "Hormonlar kanla taşınmaz ve hedef dokular üzerinde etkili olmaz.", "Sinirsel ve hormonal düzenleme hız ve etki süresi bakımından tamamen aynıdır."], "İç salgı bezleri ilişkili bir sistemdir; belirtilerden hastalık tanısı konmaz ve sağlık soruları uzmanla değerlendirilir."),
    ("tr-g06-fen-bilimleri-note-015", "Aynı yaştaki iki öğrencinin boy uzaması ve ses değişimi aynı zamanda gerçekleşmiyor.", "Sağlık kaynağı ergenlik değişimlerinin kişiden kişiye farklı zamanda ve hızda görülebileceğini açıklıyor.", "Ergenlikte bedensel ve duygusal değişimler normal gelişimin parçasıdır; başlangıç ve hız bireyler arasında farklı olabilir.", "Karşılaştırma ve alaydan kaçınıp güvenilir yetişkin veya sağlık uzmanından doğru bilgi almak gerekir.", "Zaman farklılığına ilişkin kaynak, tek bir gelişim takviminin herkese uygulanamayacağını gösterir.", ["Ergenlikte bütün bireylerde her değişim aynı gün başlar.", "Bedensel farklılıklar öğrencilerle alay etmeyi bilimsel olarak haklı çıkarır.", "Duygusal değişimler ergenlik süreciyle hiçbir biçimde ilişkili değildir."], "Ergenlik bilgisi bireysel farklılık, mahremiyet ve saygıyla ele alınır; olağan dışı kaygıda güvenilir yetişkin ve uzman desteği aranır."),
    ("tr-g06-fen-bilimleri-note-016", "Bir öğrenci düzensiz uyuyor, enerji içeceği tüketiyor ve baş ağrısında arkadaşının ilacını kullanmayı düşünüyor.", "Güvenilir sağlık kaynağı yeterli uyku, dengeli beslenme, hareket ve ilaçların yalnız uygun yetişkin/uzman yönlendirmesiyle kullanılmasını öneriyor.", "Denetleyici ve düzenleyici sistemlerin sağlığı düzenli yaşam alışkanlıklarıyla korunur; başkasının ilacı kullanılmamalıdır.", "Uyku düzeni kurmak, enerji içeceğini bırakmak ve ağrı için ailesiyle sağlık uzmanına başvurmak gerekir.", "Kaynak önerileri, hızlı çözüm olarak başkasının ilacını kullanmanın güvenli olmadığını gösterir.", ["Arkadaşta işe yarayan ilaç aynı belirtiyi yaşayan herkes için güvenlidir.", "Uyku ve beslenme sinir sistemi sağlığını etkilemez.", "Enerji içecekleri çocuklarda sınırsız tüketildiğinde daima yararlıdır."], "Sağlık davranışı güvenilir kaynak ve uzman desteğine dayanır; soru bankası tanı veya kişisel tedavi önerisi vermez."),
    ("tr-g06-fen-bilimleri-note-017", "El feneri parlak metal, mat duvar ve buruşturulmuş folyo yüzeylere aynı açıyla tutuluyor.", "Parlak metalde belirgin tek yansıma, mat ve kırışık yüzeylerde birçok yöne dağılan ışık görülüyor.", "Düz yüzey düzgün, pürüzlü yüzey dağınık yansıma oluşturur; her küçük bölgede yansıma kuralı yine geçerlidir.", "Yüzeyleri aynı ışık ve açı koşulunda karşılaştırıp yansıyan ışığın yön dağılımını kaydetmek gerekir.", "Dağılım farkı, yüzey pürüzlülüğünün yansımanın düzenini etkilediğini gösterir.", ["Pürüzlü yüzeyler ışığı hiç yansıtmaz.", "Dağınık yansımada yansıma kuralları tümüyle geçersizdir.", "Yüzey yapısı yansıyan ışığın yönünü etkilemez."], "Düzgün ve dağınık yansıma ışığın varlığıyla değil, yüzey normallerinin düzeni ve ışınların yön dağılımıyla ayırt edilir."),
    ("tr-g06-fen-bilimleri-note-018", "Bir ışın aynaya yüzey normaliyle 35° açı yaparak geliyor.", "Yansıyan ışının normalin öteki tarafında yine 35° olduğu ölçülüyor.", "Yansıma kanununa göre gelme açısı yansıma açısına eşittir ve iki açı yüzey normaline göre ölçülür.", "Normal çizip 35°'lik gelme ve yansıma açılarını normalin iki yanında göstermek gerekir.", "Eşit ölçümler, açının ayna yüzeyine değil normale göre tanımlandığını gösterir.", ["Yansıma açısı her zaman gelme açısının iki katıdır.", "Gelme açısı ayna yüzeyi ile ışın arasından ölçülür.", "Yüzey normali aynaya paralel çizilir."], "Açı çiziminde ışın yönü, gelme noktası ve dik normal açık olmalıdır; doğru cevap şekil başlığında sızdırılmaz."),
    ("tr-g06-fen-bilimleri-note-019", "Mağaza güvenlik aynası geniş koridoru gösteriyor, makyaj aynası yakındaki yüzü büyütüyor ve duvar aynası doğal boyda görüntü veriyor.", "Güvenlik aynası tümsek, yakından büyüten ayna çukur, duvar aynası düzdür.", "Düz, çukur ve tümsek aynalar görüntü özellikleri ve görüş alanları nedeniyle farklı amaçlarda kullanılır.", "Kullanım amacını görüş alanı ve görüntü büyüklüğüyle eşleştirerek uygun ayna türünü seçmek gerekir.", "Üç kullanımın farklı sonuçları, bütün aynaların aynı görüntüyü oluşturmadığını gösterir.", ["Tümsek ayna dar görüş alanı için kullanılır ve her zaman büyük görüntü verir.", "Düz ayna cismi her uzaklıkta ters gösterir.", "Çukur aynanın görüntüsü cismin uzaklığına göre hiç değişmez."], "Ayna türü ezber etiketiyle değil, yüzey şekli, cisim uzaklığı ve istenen görüş/görüntü özelliğiyle seçilir."),
    ("tr-g06-fen-bilimleri-note-020", "Güneş altında eş özdeş siyah ve beyaz metal kutular bırakılıyor.", "On dakika sonra siyah kutunun sıcaklığı 42°C, beyaz kutunun sıcaklığı 34°C ölçülüyor.", "Koyu yüzeyler gelen ışığın daha büyük bölümünü soğurabildiği için aynı koşullarda daha fazla ısınabilir.", "Kutuların malzeme, boyut, başlangıç sıcaklığı ve ışık süresini eşit tutup yalnız rengi değiştirmek gerekir.", "Siyah kutudaki daha büyük sıcaklık artışı, yüzey renginin soğurma miktarını etkilediğini destekler.", ["Beyaz yüzey bütün ışığı soğurduğu için daima daha çok ısınır.", "Renk ile ışık soğurulması arasında hiçbir ilişki yoktur.", "Deneyde kutu malzemelerini de değiştirmek renk etkisini daha doğru ölçer."], "Soğurulma çıkarımı kontrollü deney ve sıcaklık verisiyle yapılır; tek ölçüm bütün malzemelere koşulsuz genellenmez."),
    ("tr-g06-fen-bilimleri-note-021", "Dar beyaz ışık demeti üçgen prizmaya gönderilip beyaz ekrana düşürülüyor.", "Ekranda kırmızıdan mora uzanan renk şeridi görülüyor; renkler ikinci düzenekte yeniden birleştirilebiliyor.", "Beyaz ışık farklı renk bileşenlerinden oluşur ve prizma bu bileşenleri farklı miktarda kırarak ayırabilir.", "Işık kaynağı, prizma ve ekranı hizalayıp ortam ışığını azaltarak renk şeridini gözlemek gerekir.", "Tek beyaz demetten birden çok rengin ayrılması, beyaz ışığın bileşik yapısını gösterir.", ["Prizma renkleri yoktan üretir; beyaz ışıkta renk bileşeni bulunmaz.", "Beyaz ışık yalnız kırmızı ışıktan oluşur.", "Renk şeridi ışığın kırılmasıyla hiçbir ilişkisi olmayan ekran boyasıdır."], "Beyaz ışığın bileşimi deney düzeneğiyle gösterilir; şekil gerçek ışın yolu ve ekran gözlemiyle tutarlı olmalıdır."),
    ("tr-g06-fen-bilimleri-note-022", "Kırmızı bir cisim beyaz, kırmızı ve mavi ışık altında ayrı ayrı gözleniyor.", "Cisim beyaz ve kırmızı ışıkta kırmızı, mavi ışıkta çok koyu görünüyor.", "Cismin görünen rengi üzerine düşen ışık ile cismin yansıttığı renklerin birlikte sonucudur.", "Işık rengini tek değişken yapıp aynı cismi ve ortamı koruyarak yansıyan ışığı karşılaştırmak gerekir.", "Mavi ışıkta koyulaşma, cismin yansıtacağı kırmızı bileşenin ortamda bulunmamasıyla açıklanır.", ["Bir cismin rengi aydınlatma değişse de her koşulda aynı parlaklıkta görünür.", "Kırmızı cisim mavi ışığı tamamen kırmızıya dönüştürür.", "Görünen renk yalnız cismin adına bağlıdır, gelen ışıkla ilişkili değildir."], "Renk görme yansıma ve soğurulmanın birleşimidir; ışık kaynağının tayfı bilinmeden yalnız cisim etiketinden sonuç çıkarılmaz."),
    ("tr-g06-fen-bilimleri-note-023", "Bir okul çatısında elektrik üreten paneller, yan binada su ısıtan güneş kolektörleri bulunuyor.", "Paneller elektrik sayacına, kolektörler sıcak su deposuna bağlıdır.", "Güneş enerjisi fotovoltaik panellerle elektriğe, güneş kolektörleriyle ısı enerjisine dönüştürülebilir.", "İhtiyaç elektrikse panel, sıcak suysa uygun ısıl kolektör seçip verimi gölgelenme ve yönle değerlendirmek gerekir.", "Farklı çıkış bağlantıları, iki sistemin aynı enerji dönüşümünü yapmadığını gösterir.", ["Her güneş enerjisi düzeneği yalnız sıcak su üretir.", "Fotovoltaik panel Güneş ışığını doğrudan kömür yakarak elektriğe çevirir.", "Gölgelenme ve panel yönü enerji üretimini etkilemez."], "Yenilenebilir uygulama seçimi enerji ihtiyacı, dönüşüm türü, yerel koşullar ve yaşam döngüsü etkileriyle değerlendirilir."),
    ("tr-g06-fen-bilimleri-note-024", "Metal köprüde yazın genleşme boşlukları daralıyor, kışın yeniden genişliyor.", "Aynı metal parça ısıtıldığında uzunluğu az miktarda artıyor, soğutulduğunda başlangıca yaklaşıyor.", "Maddeler ısıtıldığında genellikle genleşir, soğutulduğunda büzülür; yapı tasarımında bu değişim için pay bırakılır.", "Köprü birleşimlerinde hesaplanmış genleşme boşluğu kullanıp sıcaklık aralığına göre denetlemek gerekir.", "Mevsimle değişen boşluk, metalin sıcaklığa bağlı boyut değişimini destekler.", ["Metal ısıtıldığında her zaman büzülür ve boşluk büyür.", "Genleşme boşluğu köprünün sıcaklık değişiminden etkilenmesini artırmak için bırakılır.", "Soğuma ve ısınma maddelerin boyutunu hiçbir zaman değiştirmez."], "Genleşme tahmini madde türü, başlangıç boyutu ve sıcaklık değişimine bağlıdır; günlük örnek bilimsel ölçümle ilişkilendirilir."),
    ("tr-g06-fen-bilimleri-note-025", "Saf bir madde ısıtılırken sıcaklığı düzenli kaydediliyor.", "Sıcaklık 80°C'ye kadar artıyor, kaynama boyunca bir süre 80°C'de kalıyor, sıvı bitince yeniden artıyor.", "Saf maddede aynı basınçta kaynama sırasında sıcaklık bir süre sabit kalabilir ve bu değer ayırt edici özelliktir.", "Isıtma gücünü düzenli tutup sıcaklık-zaman tablosu oluşturmak ve hâl değişimi platosunu belirlemek gerekir.", "Sabit sıcaklık bölgesi, verilen koşulda hâl değişiminin gerçekleştiğini gösterir.", ["Kaynama boyunca saf maddenin sıcaklığı zorunlu olarak sürekli hızla artar.", "Kaynama noktası maddeyi ayırt etmede hiçbir bilgi vermez.", "Sıcaklık sabit kaldığında maddeye hiç enerji aktarılmaz."], "Hâl değişim noktası kontrollü deney, güvenli ısıtma ve basınç koşuluyla belirlenir; bilinmeyen maddeye doğrudan temas edilmez."),
    ("tr-g06-fen-bilimleri-note-026", "Bir taşın kütlesi 78 g, suya batırıldığında hacim artışı 30 cm³ ölçülüyor.", "Hesap 78/30=2,6 g/cm³ sonucunu veriyor.", "Yoğunluk bir maddenin birim hacimdeki kütlesidir ve d=m/V bağıntısıyla hesaplanır.", "Kütleyi hacme bölüp birimi g/cm³ olarak yazmak ve ölçüm belirsizliğini korumak gerekir.", "Kütle-hacim oranının 2,6 çıkması taşın yoğunluğunu verir.", ["Yoğunluk hacmin kütleye bölünmesiyle 30/78 hesaplanır.", "Kütle gram ve hacim santimetreküp iken yoğunluğun birimi yalnız gramdır.", "Cismin suya batması kütlesini 30 grama düşürür."], "Sayısal yoğunluk sorusunda ölçüm verileri, işlem, birim ve fiziksel anlam atomik olarak uyuşmalıdır."),
    ("tr-g06-fen-bilimleri-note-027", "Eşit hacimli alüminyum ve demir bloklar tartılıyor.", "Alüminyum 54 g, demir 158 g geliyor; hacimleri 20 cm³.", "Eşit hacimde kütlesi daha büyük olan maddenin yoğunluğu daha büyüktür.", "Her blok için kütle/hacim oranını hesaplayıp aynı birimle karşılaştırmak gerekir.", "Demirin eşit hacimde daha ağır olması yoğunluğunun daha büyük olduğunu gösterir.", ["Eşit hacimli bütün maddelerin kütlesi zorunlu olarak eşittir.", "Kütlesi büyük olan cismin yoğunluğu hacimden bağımsız olarak her durumda küçüktür.", "Yoğunluk karşılaştırmasında birimlerin aynı olması gerekmez."], "Yoğunluk madde miktarından bağımsız ayırt edici oran olarak yorumlanır; karşılaştırmada ölçü birimleri eşitlenir."),
    ("tr-g06-fen-bilimleri-note-028", "Kışın gölün üst yüzeyi donar fakat altındaki su sıvı kalır.", "Buz yüzeyde yüzer ve alttaki su ile soğuk hava arasında bir tabaka oluşturur.", "Buz sıvı sudan daha düşük yoğunluklu olduğu için yüzer; yüzeydeki buz tabakası alttaki suyun hızlı ısı kaybını azaltabilir.", "Modelde buzun üstte, daha yoğun sıvı suyun altta kaldığını ve ısı aktarımının yavaşladığını göstermek gerekir.", "Yüzeyden donma ve altta sıvı su kalması, yoğunluk farkının canlılar için koruyucu sonuç doğurabildiğini gösterir.", ["Buz sudan daha yoğun olduğu için gölün dibine çöker.", "Göl bütünüyle dipten başlayarak donar.", "Yüzeydeki buz tabakası alttaki suyun ısı kaybını her zaman hızlandırır."], "Suyun donma davranışı yoğunluk modeliyle açıklanır; doğadaki sonuç sıcaklık, derinlik ve çevre koşullarıyla birlikte değerlendirilir."),
    ("tr-g06-fen-bilimleri-note-029", "İki eş hacimli kutudan birinde tanecikler seyrek, diğerinde aynı hacme daha fazla tanecik yerleştirilmiş modelle gösteriliyor.", "İkinci kutunun toplam kütlesi daha büyük ölçülüyor.", "Aynı hacimde daha fazla kütle bulunan model daha yüksek yoğunluğu temsil eder.", "Modelde hacimleri eşit tutup tanecik sayısı/kütlesi farkını açık etiketlemek gerekir.", "Eşit hacimde kütle artışı, yoğunluk oranının yükseldiğini gösterir.", ["Tanecik sayısı artsa da eşit hacimde kütle ve yoğunluk değişmez.", "Yoğunluk modeli yalnız kutunun dış rengini göstermelidir.", "Aynı hacimde daha az kütle daha yüksek yoğunluk demektir."], "Tanecik modeli yoğunluğun doğrudan fotoğrafı değildir; kütle-hacim ilişkisini temsil eden varsayımlar ve sınırlar açıklanır."),
    ("tr-g06-fen-bilimleri-note-030", "Basit devrede bakır tel, plastik çubuk, grafit uç ve cam parça sırayla boşluğa yerleştiriliyor.", "Ampul bakır ve grafitte yanıyor, plastik ve camda yanmıyor.", "Elektrik iletkenleri akımın geçmesine izin verirken yalıtkanlar devrede akımı belirgin biçimde sınırlar.", "Aynı pil ve ampulle yalnız test maddesini değiştirip sonuçları güvenli düşük gerilim devresinde kaydetmek gerekir.", "Ampulün yalnız bakır ve grafitte yanması bu maddelerin düzenekte iletken davrandığını gösterir.", ["Plastik ve cam ampulü yakmadığı için güçlü iletkendir.", "Bir maddenin iletkenliğini test ederken pili doğrudan şehir elektriğine bağlamak gerekir.", "Grafit metal olmadığı için hiçbir koşulda elektrik iletemez."], "İletkenlik deneyinde güvenli kaynak, kapalı devre ve tek değişken kullanılır; ev prizinde deney yapılmaz."),
    ("tr-g06-fen-bilimleri-note-031", "Aynı maddeden eş kalınlıkta iki telden uzun olanı devreye bağlandığında ampul daha sönük yanıyor.", "Tel uzunluğu iki katına çıkarken pil, ampul, kesit ve madde cinsi sabit tutuluyor.", "Aynı cins ve kesitte iletken uzunluğu arttıkça direnç artar, devredeki ampul parlaklığı azalabilir.", "Yalnız tel uzunluğunu değiştirip parlaklığı veya akımı ölçerek adil karşılaştırma yapmak gerekir.", "Uzun telde sönükleşme, daha uzun iletken yolunun direnci artırdığını destekler.", ["Tel uzadıkça direnç azalır ve ampul zorunlu olarak daha parlak yanar.", "Uzunluk etkisini ölçerken telin cinsini ve kalınlığını da değiştirmek gerekir.", "Ampul parlaklığı ile devre direnci arasında hiçbir ilişki yoktur."], "Direnç karşılaştırmasında uzunluk, kesit ve cins ayrı değişkenlerdir; yalnız biri değiştirilerek neden çıkarımı yapılır."),
    ("tr-g06-fen-bilimleri-note-032", "Sürgülü reosta seri devrede hareket ettiriliyor.", "Devreye katılan direnç teli uzadığında ampermetre değeri ve ampul parlaklığı azalıyor.", "Reosta devreye giren tel uzunluğunu değiştirerek direnci ve buna bağlı akım/parlaklığı ayarlar.", "Sürgü konumlarını aynı pil ve ampulle karşılaştırıp devreye katılan tel uzunluğunu şemada göstermek gerekir.", "Uzun yol ile düşük akımın birlikte görülmesi, reostanın direnci artırdığını gösterir.", ["Reostada devreye giren tel uzadıkça direnç azalır ve akım artar.", "Reostanın sürgü konumu devreyi hiçbir biçimde etkilemez.", "Ampul parlaklığını ayarlamak için reostayı pile paralel rastgele bağlamak yeterlidir."], "Reosta sorusunda bağlantı uçları ve akım yolu görünür olmalıdır; yalnız sürgünün fiziksel yönünden ezber sonuç çıkarılmaz."),
    ("tr-g06-fen-bilimleri-note-033", "Bir çayırda farklı bitki, böcek ve kuş türlerinin bulunduğu alan ile tek tür çim bulunan alan kuraklık sonrası karşılaştırılıyor.", "Çeşitli alanda bazı türler azalsa da besin ağı sürüyor; tek tür alanda örtü büyük ölçüde kayboluyor.", "Biyoçeşitlilik ekosistemin işlev ve değişimlere dayanıklılığına katkı sağlayabilir.", "Tür sayısıyla birlikte türlerin görevlerini ve kuraklık sonrası ekosistem işlevlerini ölçmek gerekir.", "Çeşitli alanın işlevini daha iyi sürdürmesi, çeşitliliğin dayanıklılıkla ilişkisini destekler.", ["Biyoçeşitlilik yalnız görüntü güzelliğidir ve ekosistem işlevini etkilemez.", "Tek tür bulunan her alan bütün değişimlere daha dayanıklıdır.", "Bir tür azalınca diğer türlerin ekosistem rolü hiçbir önem taşımaz."], "Biyoçeşitlilik tür sayısından öte genetik, tür ve ekosistem çeşitliliğini; aralarındaki işlevsel ilişkileri kapsar."),
    ("tr-g06-fen-bilimleri-note-034", "Sulak alan çevresinde yapılaşma ve kirlilik artarken kuş türü sayıları beş yıl boyunca kaydediliyor.", "Yapılaşma alanı artıyor, su kalitesi düşüyor ve gözlenen kuş türü sayısı 42'den 27'ye geriliyor.", "Habitat kaybı ve kirlilik biyoçeşitliliği tehdit edebilir; zaman içindeki eş değişim neden araştırması için güçlü işarettir.", "Arazi, su kalitesi ve tür verilerini aynı dönem için karşılaştırıp başka etkenleri de incelemek gerekir.", "Eş zamanlı habitat ve tür değişimi tehdit olasılığını destekler ancak tek başına bütün nedenleri kesinleştirmez.", ["Tür sayısı azalırken habitat kaybı artıyorsa iki veri arasında hiçbir ilişki araştırılamaz.", "Beş yıllık tek alan verisi dünyadaki bütün kuş türleri için kesin sonuç verir.", "Su kirliliği sulak alan canlılarını hiçbir biçimde etkileyemez."], "Veriye dayalı tahmin eğilimi gösterir; nedensellikte zaman, karşılaştırma alanı ve alternatif etkenler ayrıca incelenir."),
    ("tr-g06-fen-bilimleri-note-035", "Kapalı bir odada bakımsız soba yakıldığında baş ağrısı ve sersemlik yaşayan kişiler oluyor.", "Baca çekişi yetersiz ve ölçüm cihazı karbonmonoksit uyarısı veriyor.", "Eksik yanma sonucu oluşabilen karbonmonoksit renksiz ve kokusuz zehirli gazdır; doğru baca, bakım, havalandırma ve alarm yaşam güvenliği için önemlidir.", "Kişileri temiz havaya çıkarıp acil yardım çağırmak, kaynağı uzman olmadan yeniden yakmamak ve sistemi yetkili kişiye kontrol ettirmek gerekir.", "Belirtilerle alarmın birlikte görülmesi, olayı sıradan koku rahatsızlığı saymanın tehlikeli olduğunu gösterir.", ["Karbonmonoksit güçlü kokusuyla her zaman kolayca fark edilir.", "Baş ağrısı olan kişiyi aynı odada tutup sobayı daha çok yakmak güvenlidir.", "Baca bakımı ve havalandırma yakıt güvenliğini etkilemez."], "Yakıt soruları yüksek risklidir; belirtilerde ortam terk edilir ve acil/uzman desteği alınır, öğrenciye müdahale deneyi yaptırılmaz."),
    ("tr-g06-fen-bilimleri-note-036", "Mahalle deresinde plastik atık ve bulanıklık artışı gözleniyor.", "Üç noktada haftalık atık sayımı ve bulanıklık ölçümü, pazar alanına yakın noktada en yüksek değerleri gösteriyor.", "Çevre sorununa çözüm, kaynağı belirleyen yerel veri ve etkisi ölçülebilir önleme adımlarıyla geliştirilmelidir.", "Pazar alanında atık azaltma-ayırma düzeni kurup dereye ulaşan atığı aynı ölçümlerle önce-sonra karşılaştırmak gerekir.", "En yüksek değerlerin pazar yakınında olması müdahale önceliğini gösterir; tek başına bütün kirliliğin tek kaynağını kanıtlamaz.", ["Çözüm seçmek için yerel ölçüm yapmaya gerek yoktur.", "Dere temizlendikten sonra atık kaynağını azaltmak gereksizdir.", "Tek bir fotoğraf bütün yılın kirlilik düzeyini kesin gösterir."], "Çevre çözümü belirtiyi toplamakla kalmaz; kaynağı azaltır, paydaşları içerir ve aynı göstergelerle etkisini izler."),
]


if __name__ == "__main__":
    if len(FEN_CASES) != 36 or len({case[0] for case in FEN_CASES}) != 36:
        raise SystemExit("science case coverage must be exactly 36 unique notes")
